(function () {
'use strict';
const {catalogs,lessons,describeProperty,propertyValues}=window.CSSLab;

// Las fichas combinan explicaciones concretas con el contexto real del ejemplo.
const topics=[
  {test:/^--/,lesson:'variables',use:'Guardar una decisión de diseño, como un color o un espacio, y reutilizarla sin repetir el mismo valor.',needs:'Define un nombre que empiece por -- y úsalo mediante var(). El nombre distingue mayúsculas y minúsculas.',mistakes:['Escribir --* literalmente: es una familia de nombres; usa uno concreto como --acento.','Definir una variable no cambia nada hasta que una propiedad la utiliza.'],related:['color','background-color']},
  {test:/^(margin|padding|gap|row-gap|column-gap)/,lesson:'modelo-caja',use:'Separar contenido para que una tarjeta, una lista o un grupo de botones tenga espacio para respirar.',needs:'Distingue tres lugares: margin está fuera del borde, padding está dentro y gap separa hijos en un contexto que lo admita.',mistakes:['Confundir espacio interior con exterior produce resultados diferentes aunque el número de píxeles sea el mismo.','En Flexbox y Grid, gap se coloca en el contenedor, no en cada hijo.'],related:['margin','padding','gap']},
  {test:/^(width|height|min-width|max-width|min-height|max-height|aspect-ratio|box-sizing|.*inline-size|.*block-size)$/,lesson:'dimensiones',use:'Dar tamaño a una tarjeta, limitar el ancho de lectura o mantener la proporción de una imagen.',needs:'Comprueba el tamaño del contenedor y el valor de box-sizing. El contenido, el relleno y el borde no siempre se incluyen dentro de width.',mistakes:['Un ancho fijo puede desbordar en una pantalla más pequeña.','Una altura fija puede cortar texto si aumenta el tamaño de letra.'],related:['width','max-width','min-height','box-sizing']},
  {test:/^(background|border(?!-collapse|-spacing)|outline|box-shadow)/,lesson:'bordes',use:'Diferenciar superficies y dibujar límites o profundidad en tarjetas y controles.',needs:'El fondo, el borde, el contorno y la sombra son capas distintas. Un efecto dibujado fuera de la caja puede no reservar espacio.',mistakes:['Una abreviatura puede reiniciar valores que no incluyes.','No elimines el indicador de foco de un control sin proporcionar otro visible.'],related:['background-color','border','border-radius','box-shadow']},
  {test:/^(color|opacity|mix-blend-mode|isolation|color-scheme)$/,lesson:'colores',use:'Crear jerarquía, expresar un estado o separar una superficie del texto que contiene.',needs:'Comprueba el contraste entre el texto y el fondo. Un cambio de color no siempre modifica el fondo o la transparencia de los hijos.',mistakes:['Usar solo el color para indicar un error deja fuera a quienes no distinguen ese cambio.','opacity vuelve transparente el conjunto del elemento, también su contenido.'],related:['color','background-color','opacity']},
  {test:/^(font|line-height|letter-spacing|word-spacing)/,lesson:'tipografia',use:'Hacer que títulos, párrafos y etiquetas sean legibles y tengan una jerarquía clara.',needs:'La familia de fuente debe estar disponible o tener una alternativa. Algunas características solo se aprecian con una fuente que las admita.',mistakes:['Pedir un peso o un eje que la fuente no ofrece puede dar un resultado distinto del esperado.','Un tamaño pequeño y poco espacio entre líneas dificultan la lectura.'],related:['font-family','font-size','font-weight','line-height']},
  {test:/^(text|white-space|overflow-wrap|word-break|hyphens)/,lesson:'texto',use:'Controlar cómo se leen, se alinean y se reparten las líneas de un texto.',needs:'El ancho disponible y las reglas de salto de línea influyen en el resultado. Para idiomas y separación silábica, indica lang en el HTML.',mistakes:['Cambiar la alineación del texto no mueve la caja completa.','Ocultar texto importante para que quepa puede hacer que se pierda información.'],related:['text-align','white-space','overflow-wrap','text-overflow']},
  {test:/^(flex|order)/,lesson:'flexbox',use:'Distribuir botones, enlaces o tarjetas en una fila o una columna.',needs:'El padre necesita display: flex o inline-flex. Las propiedades de los elementos flex se escriben en los hijos directos.',mistakes:['Poner flex-grow en el contenedor no hace crecer a sus hijos.','El orden visual no cambia el orden de lectura ni el recorrido del teclado.'],related:['display','flex-direction','flex-wrap','flex']},
  {test:/^grid/,lesson:'grid',use:'Organizar una composición con filas y columnas que se coordinan entre sí.',needs:'El padre necesita display: grid o inline-grid. Distingue las pistas del contenedor de la posición de cada hijo.',mistakes:['Una propiedad de posición de un elemento no sustituye la definición del Grid en el padre.','Un texto muy largo puede exigir minmax(0, 1fr) o un mínimo adecuado.'],related:['grid-template-columns','grid-template-rows','gap','grid-column']},
  {test:/^(align|justify|place)-/,lesson:'alineacion-flex',use:'Alinear elementos o distribuir el espacio disponible dentro de una composición.',needs:'Identifica el contexto: Flexbox y Grid no interpretan todos los ejes de la misma forma. En Flexbox, flex-direction define el eje principal.',mistakes:['Con flex-direction: column, el eje principal deja de ser horizontal en la escritura habitual.','Si no hay espacio libre, algunos cambios de alineación apenas se ven.'],related:['display','flex-direction','justify-content','align-items']},
  {test:/^(position|inset|top|right|bottom|left|z-index)/,lesson:'posicion',use:'Anclar una etiqueta a una tarjeta, desplazar una caja o controlar qué elemento se dibuja delante.',needs:'Comprueba qué ancestro establece la referencia de posición y si existen contextos de apilamiento.',mistakes:['top y left no desplazan una caja con position: static.','Un número enorme de z-index no permite salir del contexto de un ancestro.'],related:['position','inset','z-index']},
  {test:/^(overflow|resize|scroll|overscroll|touch-action)/,lesson:'overflow',use:'Gestionar contenido que no cabe y decidir cómo se puede recorrer.',needs:'Para observar un desbordamiento necesitas contenido más grande que un área limitada. Para scroll snap necesitas un contenedor y destinos.',mistakes:['overflow: hidden puede esconder información en lugar de resolver un ancho incorrecto.','Cambiar estilos de scroll puede depender del navegador, del dispositivo y de sus preferencias.'],related:['overflow','overflow-x','overflow-y','scroll-snap-type']},
  {test:/^(transform|translate|rotate|scale|perspective|backface)/,lesson:'transiciones',use:'Mover, girar o escalar un componente para una composición o un estado de interacción.',needs:'Una transformación cambia el dibujo de la caja y normalmente conserva su espacio original en el flujo.',mistakes:['El orden de las funciones de transform cambia el resultado.','Una transformación también puede crear una referencia o un contexto de apilamiento nuevo.'],related:['transform','transform-origin','transition']},
  {test:/^animation/,lesson:'animaciones',use:'Reproducir una secuencia de cambios definidos con @keyframes.',needs:'Necesitas una secuencia con nombre y una duración adecuada. El ejemplo ya prepara la secuencia pulso.',mistakes:['Un nombre que no coincide con @keyframes no reproduce esa secuencia.','Las preferencias de reducir movimiento pueden detener o acortar el efecto.'],related:['animation','animation-name','animation-duration','animation-play-state']},
  {test:/^transition/,lesson:'transiciones',use:'Hacer gradual un cambio entre dos estados, por ejemplo al pasar el cursor por un botón.',needs:'La propiedad debe cambiar de valor. En este ejemplo, pasa el cursor o enfoca el botón con Tab.',mistakes:['Una transición declarada sin cambio de estado no tiene nada que interpolar.','No todas las propiedades se interpolan igual; evita transition: all si solo necesitas una.'],related:['transition','transition-property','transition-duration','transform']},
  {test:/^(filter|backdrop-filter|clip-path|mask)/,lesson:'sombras',use:'Filtrar o recortar lo que se dibuja en una superficie o una imagen.',needs:'Estos efectos pueden cambiar la pintura sin modificar el espacio que ocupa la caja. backdrop-filter necesita dejar ver el fondo.',mistakes:['Recortar una figura no hace que las cajas vecinas sigan su silueta.','Los desenfoques y filtros grandes pueden aumentar el trabajo de renderizado.'],related:['filter','backdrop-filter','clip-path','mask-image']},
  {test:/^(list-style|counter-|content$)/,lesson:'listas',use:'Personalizar marcadores, numerar pasos o añadir una decoración generada con CSS.',needs:'Para marcadores necesitas elementos de lista; para content suele utilizarse ::before o ::after.',mistakes:['No sustituyas información esencial del HTML por texto generado.','Un contador necesita una inicialización y un lugar donde mostrar su valor.'],related:['list-style-type','content','counter-reset','counter-increment']},
  {test:/^(border-collapse|border-spacing|table-layout|caption-side|empty-cells|vertical-align)$/,lesson:'tablas',use:'Presentar datos de una tabla con columnas, bordes y alineación legibles.',needs:'Usa la estructura de tabla adecuada. Algunas propiedades solo se observan con un modelo de bordes o un tipo de caja específico.',mistakes:['border-spacing no separa celdas si los bordes están colapsados.','vertical-align no centra cualquier bloque de una interfaz.'],related:['border-collapse','border-spacing','table-layout']},
  {test:/^column-/,lesson:'flotantes',use:'Repartir un texto largo en columnas, como en una publicación editorial.',needs:'Prepara un contenedor multicolumna y suficiente texto. El alto disponible puede influir en el reparto.',mistakes:['Las columnas de texto no se comportan igual que las columnas de Grid.','Forzar medidas pequeñas puede dificultar la lectura o crear desbordamientos.'],related:['column-count','column-width','column-gap']},
  {test:/^(object-fit|object-position)$/,lesson:'imagenes',use:'Ajustar una fotografía a una miniatura sin deformarla y elegir qué zona se ve.',needs:'La propiedad actúa sobre contenido reemplazado, como img. Para notar el encuadre, la caja y la imagen deben tener proporciones distintas.',mistakes:['No funciona como background-size sobre un div cualquiera.','cover puede recortar parte de una foto; considera qué contenido necesitas conservar.'],related:['object-fit','object-position','aspect-ratio']},
  {test:/^(cursor|pointer-events|user-select|accent-color|appearance|caret-color)$/,lesson:'formularios',use:'Presentar estados y señales de interacción de controles, selección y edición.',needs:'Prueba el control correspondiente: escribir, seleccionar, enfocar o mover el puntero puede ser necesario para ver el cambio.',mistakes:['Cambiar el cursor no convierte un div en un botón accesible.','Un estilo visual no reemplaza label, button ni los estados que aporta HTML.'],related:['accent-color','appearance','cursor']},
  {test:/^(contain|content-visibility|will-change)/,lesson:'rendimiento',use:'Reducir trabajo de renderizado cuando una página o un componente lo necesitan.',needs:'Primero construye una interfaz que funcione y mide el problema. La contención puede cambiar el layout, los recortes y el apilamiento.',mistakes:['No apliques optimizaciones a todo por intuición.','Reservar demasiados recursos con will-change puede empeorar el rendimiento.'],related:['contain','content-visibility','contain-intrinsic-size']},
  {test:/^(container-|container$)/,lesson:'container-queries',use:'Hacer que un componente responda al espacio de su contenedor, en lugar de toda la ventana.',needs:'Prepara un ancestro como contenedor y aplica las reglas de la consulta a un descendiente.',mistakes:['El elemento que consultas y el que rediseñas no son intercambiables.','Una consulta de tamaño necesita la configuración de contenedor correspondiente.'],related:['container-type','container-name']},
  {test:/^(float|clear|shape-outside|shape-margin)/,lesson:'flotantes',use:'Hacer que el texto fluya alrededor de una figura.',needs:'Para shape-outside necesitas una caja flotante con medidas. display: flow-root puede contener flotantes.',mistakes:['Los layouts de una aplicación suelen ser más claros con Grid o Flexbox.','El texto no sigue automáticamente el border-radius de un flotante.'],related:['float','clear','shape-outside']},
  {test:/^(writing-mode|direction|unicode-bidi)/,lesson:'logicas',use:'Adaptar una interfaz al sentido y al modo de lectura de su contenido.',needs:'Distingue dirección del texto y ejes de layout. Las propiedades lógicas siguen esos ejes.',mistakes:['Izquierda no significa siempre inicio de la lectura.','Para expresar la dirección semántica del contenido, prefiere dir en HTML cuando corresponda.'],related:['writing-mode','direction','margin-inline-start']},
  {test:/^(break-|page|orphans|widows)/,lesson:'impresion',use:'Preparar cómo se divide contenido entre páginas o columnas.',needs:'Necesitas un contexto fragmentado, como impresión o varias columnas. En una vista normal puede no verse ningún cambio.',mistakes:['Una regla para impresión no se activa al estrechar la ventana.','Los ajustes del navegador y el papel elegido también influyen en los cortes.'],related:['break-before','break-after','break-inside']},
  {test:/^(fill|stroke|cx$|cy$|r$|rx$|ry$|d$|x$|y$)/,lesson:'imagenes',use:'Modificar la forma, el relleno o el contorno de figuras SVG.',needs:'La propiedad requiere una figura o un elemento SVG adecuado. No equivale siempre a estilizar una caja HTML.',mistakes:['fill no pinta el fondo de un div.','El sistema de coordenadas del SVG y sus transformaciones afectan al resultado.'],related:['fill','stroke','stroke-width']}
];

const specifics={
 color:{plain:'Cambia el color de las letras. Si un hijo no tiene otro color propio, normalmente recibe el de su padre.',when:'Para dar un color común al texto de una tarjeta o destacar un título.',values:{'#7951d8':'Un color escrito en hexadecimal: este ejemplo usa violeta.','#31916e':'Otro color hexadecimal: verde.','hsl(25 50% 45%)':'Un color descrito por matiz, saturación y luminosidad.'},exercise:'Cambia color a #31916e. Observa el título y los párrafos; el fondo debe conservar su color.',answer:'#31916e',expect:'El texto que hereda el color se vuelve verde; la superficie sigue siendo la misma.'},
 'background-color':{plain:'Pinta la superficie detrás del contenido de una caja.',when:'Para distinguir una tarjeta, un aviso o un botón del resto de la página.',mistakes:['Cambiar background-color no cambia por sí solo el color de las letras.','Un fondo con transparencia deja ver lo que hay detrás; no vuelve transparentes a los hijos.'],exercise:'Prueba #edf5ef en el fondo y comprueba si el texto sigue siendo legible.',answer:'#edf5ef',expect:'Cambia la superficie de la tarjeta, mientras el color del texto conserva sus propias reglas.'},
 margin:{plain:'Es el espacio de fuera: separa una caja de sus vecinas.',when:'Para dejar aire entre dos bloques o centrar un bloque con ancho limitado.',mistakes:['margin no añade espacio entre el texto y el borde: eso lo hace padding.','Los márgenes verticales de algunos bloques pueden colapsar; 20px y 20px no siempre se suman.'],values:{'20px':'20px en los cuatro lados.','0 auto':'0 arriba y abajo; márgenes automáticos a los lados. Para centrar un bloque necesita un ancho adecuado.','12px 24px':'12px arriba y abajo; 24px a izquierda y derecha.'},exercise:'Compara margin: 8px con margin: 32px. Mira el espacio fuera de la tarjeta.',answer:'32px',expect:'Aumenta el espacio exterior. El relleno interior de la tarjeta no cambia.'},
 padding:{plain:'Es el espacio de dentro: separa el contenido del borde de su caja.',when:'Para que el texto de una tarjeta o un botón no quede pegado al borde.',mistakes:['padding no separa dos cajas de la misma manera que margin.','No acepta valores negativos. Con content-box, puede aumentar el ancho exterior.'],values:{'24px':'24px de relleno en cada lado.','8px 30px':'8px arriba y abajo; 30px a izquierda y derecha.','32px 12px':'32px arriba y abajo; 12px a izquierda y derecha.'},exercise:'Cambia padding a 8px 30px. ¿Qué lados ganan más espacio?',answer:'8px 30px',expect:'El relleno horizontal es mayor que el vertical.'},
 gap:{plain:'Deja un espacio regular entre los hijos de un contenedor compatible, como Flexbox o Grid.',when:'Para separar botones o tarjetas sin poner un margen en cada elemento.',values:{'8px':'La misma separación pequeña entre filas y columnas.','24px':'La misma separación mayor entre filas y columnas.','12px 28px':'12px entre filas y 28px entre columnas.'},exercise:'Cambia gap de 8px a 24px y observa los huecos entre los elementos.',answer:'24px',expect:'Aumentan los huecos internos del grupo; gap no crea por sí solo un borde de espacio alrededor del conjunto.'},
 width:{plain:'Indica el ancho que prefieres para una caja, sujeto a sus límites y a su contexto.',when:'Para dimensionar una tarjeta o hacer que ocupe una parte de su contenedor.',exercise:'Prueba width: 80% y alterna el ancho de la vista previa.',answer:'80%',expect:'La caja usa un porcentaje del ancho de su referencia; no es el 80% de toda la pantalla del sitio.'},
 'max-width':{plain:'Pone un techo al ancho: la caja puede ser más estrecha, pero no superar ese límite.',when:'Para evitar que una tarjeta o un párrafo se vuelvan demasiado anchos.',exercise:'Prueba max-width: 180px y después 280px.',answer:'280px',expect:'La caja puede crecer hasta el límite indicado, si hay espacio y su ancho preferido lo permite.'},
 height:{plain:'Define el alto preferido de una caja. El contenido puede necesitar más espacio que esa altura.',when:'Para un área con tamaño controlado, como una miniatura o un panel desplazable.',mistakes:['height: 100% necesita una referencia de altura adecuada; no significa automáticamente llenar la ventana.','Si el texto crece, una altura fija puede causar desbordamiento.'],exercise:'Prueba height: 140px y después auto.',answer:'auto',expect:'Con auto, la altura se determina según las reglas del layout y el contenido; no queda fijada a 140px.'},
 'box-sizing':{plain:'Decide qué incluye el número que escribes en width o height.',when:'Para que una caja de 200px siga midiendo 200px al añadir relleno y borde.',values:{'border-box':'El ancho indicado incluye contenido, relleno y borde.','content-box':'El ancho indicado mide el contenido; relleno y borde se añaden por fuera.'},exercise:'Añade width: 200px; padding: 24px; border: 4px solid #7951d8; y compara ambos valores.',answer:'border-box',extra:'width: 200px;\n  padding: 24px;\n  border: 4px solid #7951d8;',expect:'Con border-box, la caja exterior sin margen mide 200px. Con content-box, mide 256px.'},
 'aspect-ratio':{plain:'Relaciona el ancho y el alto para mantener una forma, por ejemplo un cuadrado.',when:'Para reservar el espacio de una imagen o conservar la proporción de una miniatura.',values:{'1':'Ancho y alto iguales: proporción 1 / 1.','16 / 9':'16 partes de ancho por 9 de alto: formato apaisado.','4 / 3':'4 partes de ancho por 3 de alto.'},exercise:'Prueba aspect-ratio: 1 sin fijar ambas dimensiones a la vez.',answer:'1',expect:'Una dimensión automática puede calcularse para conservar la proporción cuadrada.'},
 display:{plain:'Decide qué tipo de caja se crea y cómo puede organizar a sus hijos.',when:'Para convertir un grupo en una fila Flexbox, una cuadrícula Grid o un bloque normal.',values:{flex:'Activa Flexbox para distribuir los hijos directos en un eje.',grid:'Activa Grid para coordinar filas y columnas.',block:'Crea una caja de bloque, que normalmente empieza en una nueva línea.',none:'Elimina la caja y su espacio del layout; sus descendientes tampoco se muestran.'},mistakes:['display: flex se escribe en el padre del grupo, no en todos sus hijos.','display: none también puede retirar el contenido del árbol de accesibilidad.'],exercise:'Alterna display: flex y display: grid. Añade grid-template-columns: 1fr 1fr para definir dos columnas.',answer:'grid',extra:'grid-template-columns: 1fr 1fr;\n  gap: 12px;',expect:'Con Grid y dos pistas, los hijos se reparten en columnas si la estructura del ejemplo tiene varios hijos.'},
 position:{plain:'Elige cómo se coloca una caja y si conserva su espacio en el flujo de la página.',when:'Para anclar una insignia a una tarjeta o crear una cabecera que se adhiera al desplazarse.',values:{static:'Posición normal; top, right, bottom y left no la desplazan.',relative:'Permite desplazarla conservando su lugar original.',absolute:'Sale del flujo; su referencia depende del bloque contenedor.',sticky:'Se mantiene en el flujo y puede adherirse al cruzar un umbral dentro de sus límites.'},exercise:'Usa position: relative y añade top: 16px. Comprueba el desplazamiento.',answer:'relative',extra:'top: 16px;',expect:'La tarjeta se dibuja más abajo y conserva su espacio original.'},
 'z-index':{plain:'Ayuda a ordenar qué caja se dibuja delante cuando varias se superponen.',when:'Para una etiqueta, un panel o un control que debe quedar por encima de otro.',exercise:'Compara z-index: 0 con z-index: 2 en la caja B.',answer:'2',expect:'Dentro del mismo contexto, la caja B puede pasar delante de la caja A con z-index: 1.'},
 overflow:{plain:'Decide qué pasa con el contenido que sale de los límites de una caja.',when:'Para crear una ventana con scroll o recortar una decoración.',values:{hidden:'Recorta lo que no cabe; sigue siendo un contenedor que puede desplazarse por API.',auto:'Permite desplazamiento cuando hace falta.',visible:'Deja dibujar contenido fuera de la caja.',clip:'Recorta y no crea un contenedor de scroll.'},exercise:'Prueba auto y después hidden; intenta recorrer el texto del panel.',answer:'auto',expect:'Con auto puedes recorrer el contenido que supera la altura disponible.'},
 'font-size':{plain:'Controla el tamaño de las letras del elemento.',when:'Para distinguir un título de un párrafo y mantener una lectura cómoda.',exercise:'Compara font-size: 14px y font-size: 24px.',answer:'24px',expect:'El texto aumenta de tamaño y puede pasar a ocupar más líneas.'},
 'font-family':{plain:'Indica con qué familia de letras se representa el texto, y cuáles probar si falta la primera.',when:'Para elegir una tipografía con alternativas que sigan disponibles.',exercise:'Prueba Georgia, serif y después system-ui, sans-serif.',answer:'system-ui, sans-serif',expect:'Cambia el dibujo de las letras y posiblemente el espacio que necesita el texto.'},
 'font-weight':{plain:'Controla el peso o grosor visual de las letras.',when:'Para destacar una palabra o construir jerarquía sin cambiar tanto el tamaño.',values:{'400':'Peso normal habitual.','700':'Peso negrita habitual.','900':'Un peso muy grueso, si la fuente lo ofrece.'},exercise:'Compara font-weight: 400 y font-weight: 700.',answer:'700',expect:'Las letras se ven más gruesas si la fuente ofrece o permite ese peso.'},
 'line-height':{plain:'Da altura a cada línea y, con ello, aire entre líneas de texto.',when:'Para que un párrafo de varias líneas no se vea apretado.',values:{'1.2':'Cada línea mide 1,2 veces el tamaño de fuente.','1.8':'Cada línea mide 1,8 veces el tamaño de fuente.','2.2':'Cada línea mide 2,2 veces el tamaño de fuente.'},exercise:'Compara line-height: 1.2 y line-height: 1.8 sin cambiar font-size.',answer:'1.8',expect:'Aumenta la separación vertical entre líneas sin aumentar el tamaño de las letras.'},
 'text-align':{plain:'Alinea las líneas y otros contenidos inline dentro de su caja.',when:'Para centrar el texto de una tarjeta o alinear una columna de datos.',values:{left:'Alinea el contenido a la izquierda.',center:'Centra el contenido inline dentro de la caja.',right:'Alinea el contenido a la derecha.',justify:'Distribuye espacio para ajustar determinadas líneas a ambos bordes.'},exercise:'Usa text-align: center. Comprueba si se centra el texto o se mueve toda la tarjeta.',answer:'center',expect:'Se centra el contenido inline; la caja del elemento conserva su posición.'},
 'text-overflow':{plain:'Indica cómo mostrar el final de una línea que ya está recortada.',when:'Para una etiqueta de una línea que termina con puntos suspensivos.',mistakes:['ellipsis no recorta por sí solo: hacen falta un ancho limitado y las condiciones de overflow adecuadas.','Para varias líneas necesitas otra técnica; esta receta es de una línea.'],exercise:'Activa ellipsis; después quita temporalmente white-space: nowrap y compara.',answer:'ellipsis',expect:'Con ancho limitado, overflow: hidden y una sola línea, el extremo puede mostrar puntos suspensivos.'},
 'flex-direction':{plain:'Elige el sentido del eje principal en el que se distribuye un grupo Flexbox.',values:{row:'El eje principal sigue la línea de escritura; normalmente es horizontal.',column:'El eje principal sigue el avance entre bloques; normalmente es vertical.','row-reverse':'Invierte el sentido visual de row.'},exercise:'Alterna row y column; mira qué sucede con el eje principal.',answer:'column',expect:'Los hijos se distribuyen siguiendo el eje de bloques en lugar del eje inline.'},
 'flex-wrap':{plain:'Decide si los hijos de Flexbox pueden saltar a una nueva línea cuando falta espacio.',values:{wrap:'Permite crear nuevas líneas.',nowrap:'Mantiene una sola línea flex; los hijos pueden encoger o desbordar.'},exercise:'Usa wrap y reduce el ancho de la vista previa.',answer:'wrap',expect:'Si los tamaños necesitan más espacio, los elementos pueden distribuirse en varias líneas.'},
 'flex-grow':{plain:'Reparte el espacio que sobra entre hijos de Flexbox según sus factores de crecimiento.',exercise:'Cambia el factor del segundo elemento de 0 a 3.',answer:'3',expect:'Si hay espacio libre positivo, el segundo hijo recibe una parte según su factor; no significa necesariamente que mida tres veces el ancho total de otro.'},
 'justify-content':{plain:'Distribuye el conjunto dentro del espacio libre. En Flexbox lo hace en el eje principal.',values:{center:'Agrupa los elementos en el centro del eje principal en Flexbox.','space-between':'Coloca el primero al inicio, el último al final y reparte los huecos intermedios.','space-around':'Reparte espacio alrededor de cada elemento.','flex-end':'Lleva el grupo al final del eje principal.'},exercise:'Prueba space-between y después cambia flex-direction a column.',answer:'space-between',extra:'flex-direction: column;',expect:'La distribución sigue el eje principal: al pasar a column, ese eje cambia.'},
 'align-items':{plain:'En Flexbox, alinea a los hijos en el eje transversal, el que cruza al eje principal.',values:{center:'Centra los elementos en su área de alineación transversal.',stretch:'Puede estirar elementos con tamaño transversal automático.','flex-end':'Los alinea al final del eje transversal.'},exercise:'Cambia align-items a flex-end en el contenedor del ejemplo.',answer:'flex-end',expect:'Los hijos se alinean al final del eje transversal; necesitan espacio libre para que el cambio se vea.'},
 'grid-template-columns':{plain:'Dibuja las columnas del Grid y decide cuánto espacio recibe cada una.',values:{'1fr 1fr':'Dos columnas que reparten el espacio flexible por igual.','repeat(3, 1fr)':'Tres columnas de una fracción cada una.','80px 1fr':'Una columna de 80px y otra que recibe el espacio flexible restante.'},exercise:'Prueba grid-template-columns: 80px 1fr.',answer:'80px 1fr',expect:'La primera pista tiene 80px; la otra reparte el espacio disponible según las reglas de Grid.'},
 'grid-column':{plain:'Coloca un hijo de Grid entre líneas de columna o le permite ocupar varias pistas.',values:{auto:'Deja la colocación al algoritmo automático.','1 / -1':'Va desde la primera hasta la última línea de la cuadrícula explícita.','span 2':'Ocupa dos pistas de columna a partir de su colocación.'},exercise:'Aplica grid-column: 1 / -1 al segundo hijo.',answer:'1 / -1',expect:'El segundo elemento abarca todas las columnas explícitas de su contenedor Grid.'},
 'border-radius':{plain:'Redondea las esquinas de la caja sin cambiar el tipo de contenido que tiene.',values:{'0':'Esquinas rectas.','16px':'El mismo radio en todas las esquinas.','50%':'Un porcentaje del tamaño de la caja: círculo si es cuadrada, elipse si es rectangular.','8px 28px':'Dos radios que se alternan entre las esquinas.'},exercise:'Prueba 0 y después 16px.',answer:'16px',expect:'Las esquinas se redondean; el contenido y la distribución mantienen sus propias reglas.'},
 border:{plain:'Dibuja el borde que rodea el contenido y su relleno.',mistakes:['Si falta un estilo visible, como solid, el borde puede no dibujarse aunque tenga ancho y color.','El grosor del borde participa en las dimensiones según box-sizing.'],exercise:'Crea border: 3px dashed #31916e.',answer:'3px dashed #31916e',expect:'Se dibuja un borde verde discontinuo de 3px.'},
 opacity:{plain:'Vuelve más transparente el elemento completo, incluido su texto y sus hijos.',values:{'.4':'Deja el conjunto al 40% de opacidad.','.75':'Deja el conjunto al 75% de opacidad.','1':'Sin transparencia aplicada por esta propiedad.'},exercise:'Prueba opacity: .4 y mira también el texto.',answer:'.4',expect:'La tarjeta y su contenido se vuelven transparentes como conjunto.'},
 transform:{plain:'Mueve, gira o escala el dibujo de una caja sin reorganizar el hueco que tenía en la página.',exercise:'Cambia transform a rotate(10deg) y después a translateX(25px).',answer:'translateX(25px)',expect:'La tarjeta se dibuja desplazada a la derecha; su hueco original en el flujo no se desplaza con ella.'},
 'object-fit':{plain:'Decide cómo encaja una imagen dentro de una caja cuyo tamaño ya está definido.',values:{cover:'Llena la caja manteniendo proporciones; puede recortar.',contain:'Muestra la imagen completa manteniendo proporciones; puede dejar bandas.',fill:'Llena las dos dimensiones de la caja y puede deformar la proporción.'},exercise:'Compara cover y contain en la miniatura cuadrada.',answer:'contain',expect:'Con contain aparece la imagen completa; puede verse el fondo alrededor.'},
 'object-position':{plain:'Elige qué parte de una imagen queda alineada con su caja.',exercise:'Con object-fit: cover, alterna left y right.',answer:'right',expect:'Cambia la zona visible del encuadre si la imagen es más ancha que su caja.'},
 'animation-duration':{plain:'Controla cuánto dura una vuelta completa de la animación.',values:{'1s':'Un ciclo de un segundo.','4s':'Un ciclo de cuatro segundos: el mismo recorrido tarda más.'},exercise:'Compara 1s y 4s sin cambiar los keyframes.',answer:'4s',expect:'La secuencia tarda más tiempo en completar cada ciclo.'},
 'transition-duration':{plain:'Define cuánto tarda en completarse el cambio entre dos estados.',exercise:'Prueba 1.5s y pasa el cursor o enfoca el botón.',answer:'1.5s',expect:'El cambio de estado tarda un segundo y medio si la propiedad está incluida y puede transicionar.'}
};

const selectorTexts={
 'Type selectors':['Selecciona etiquetas de un mismo tipo, como todos los párrafos p.','Para dar un estilo general a títulos, enlaces o párrafos.','No escribas <p> en el selector CSS: usa p.','selectores'],
 'Class selectors':['Selecciona los elementos que tienen una clase concreta. Una misma clase puede reutilizarse.','Para compartir estilos entre tarjetas, botones o avisos.','El punto va en CSS (.destacado); en HTML se escribe class="destacado" sin punto.','selectores'],
 'ID selectors':['Selecciona el elemento identificado por un ID, que debe ser único en el documento.','Para identificar un elemento concreto. Para estilos repetidos, suele convenir una clase.','La almohadilla va en CSS (#especial); en HTML se escribe id="especial". No repitas ese ID.','selectores'],
 'Universal selectors':['Selecciona cualquier elemento dentro del alcance de la regla.','Para una base común, por ejemplo box-sizing en todos los elementos.','Una regla global puede afectar mucho más contenido del que esperabas.','selectores'],
 'Attribute selectors':['Selecciona elementos por un atributo o por parte de su valor.','Para distinguir inputs por tipo o enlaces por destino.','[type="email"] compara un atributo HTML, no una clase.','atributos'],
 'Child combinator':['Selecciona hijos directos: .grupo > p no alcanza párrafos dentro de un div intermedio.','Para que una regla afecte solo a un nivel de una estructura.','Un descendiente no siempre es un hijo directo.','combinadores'],
 'Descendant combinator':['Selecciona elementos dentro de otro, aunque estén varios niveles más abajo.','Para limitar el estilo de párrafos a una sección concreta.','El espacio entre .grupo y p expresa una relación, no el mismo elemento.','combinadores'],
 'Next-sibling combinator':['Selecciona el siguiente hermano que coincida y esté inmediatamente después.','Para diseñar un párrafo que sigue justo a un título.','Los dos elementos deben compartir padre.','combinadores'],
 'Subsequent-sibling combinator':['Selecciona hermanos posteriores que coincidan, aunque haya otros entre ellos.','Para aplicar una regla a elementos que aparecen después de otro.','No selecciona hermanos anteriores ni hijos de otro nivel.','combinadores'],
 'Selector list':['Usa una coma para aplicar una misma regla a varios selectores.','Para compartir una declaración entre títulos y párrafos sin repetirla.','La coma significa «cualquiera de estos», no «uno dentro del otro».','combinadores'],
 'Nesting selector':['El símbolo & representa el selector padre dentro de una regla anidada.','Para mantener cerca los estilos relacionados de un componente.','&:hover y & :hover no expresan la misma relación.','nesting'],
 ':hover':['Coincide mientras un dispositivo apuntador señala el elemento.','Para un cambio visual adicional en enlaces o botones.','No dependas solo del hover: ofrece también una experiencia de teclado y táctil.','hover-focus'],
 ':focus-visible':['Coincide cuando un elemento tiene foco y el navegador considera útil mostrar su indicador.','Para que quien usa teclado sepa qué control está activo.','No borres el contorno sin añadir otro indicador visible.','hover-focus'],
 ':focus':['Coincide con el elemento que tiene el foco de interacción.','Para estilizar el input o botón al que se dirige el teclado.','Foco no significa que el puntero esté encima.','hover-focus'],
 ':focus-within':['Coincide con un elemento que tiene foco o contiene un descendiente enfocado.','Para resaltar un grupo de formulario al editar uno de sus controles.','La regla puede afectar al grupo completo aunque el foco esté en un hijo.','hover-focus'],
 ':active':['Coincide durante la activación del elemento, por ejemplo mientras se mantiene presionado un botón.','Para dar respuesta visual al momento de pulsar.','No representa por sí solo una pestaña seleccionada de forma persistente.','hover-focus'],
 ':checked':['Coincide con controles marcados o seleccionados, como un checkbox.','Para mostrar visualmente una opción elegida.','El estado lo aporta el control HTML: no basta con llamar checked a una clase.','formularios'],
 ':disabled':['Coincide con controles que están deshabilitados según HTML.','Para comunicar que una acción de formulario no está disponible.','Un estilo gris en un div no lo deshabilita.','formularios'],
 ':required':['Coincide con controles que tienen una restricción de obligatoriedad.','Para distinguir campos obligatorios, acompañados de una explicación clara.','El estilo no sustituye una etiqueta ni los mensajes de validación.','formularios'],
 ':valid':['Coincide con un control que satisface las restricciones de validación aplicables.','Para presentar un estado de entrada válida de forma oportuna.','La validación de HTML no sustituye la validación del servidor.','formularios'],
 ':invalid':['Coincide con un control que no satisface sus restricciones.','Para comunicar errores junto con una explicación en texto.','Un campo obligatorio vacío puede ser inválido desde el inicio; no lo señales agresivamente antes de que la persona interactúe.','formularios'],
 ':first-child':['Coincide si el elemento es el primer hijo elemento de su padre.','Para ajustar la primera fila o quitar un espacio inicial.','Cuenta a todos los hermanos elemento, no solo a los de la misma etiqueta.','estructurales'],
 ':last-child':['Coincide si el elemento es el último hijo elemento de su padre.','Para quitar el borde o margen del último elemento de una lista.','El último visual después de order no cambia su lugar en el HTML.','estructurales'],
 ':nth-child()':['Selecciona hijos según su número de orden o un patrón como 2n.','Para alternar fondos en filas o marcar cada tercer elemento.','La cuenta comienza en 1. Cuenta hermanos elemento.','estructurales'],
 ':nth-of-type()':['Cuenta entre los hermanos del mismo tipo de etiqueta.','Para seleccionar el segundo párrafo aunque haya otras etiquetas entre ellos.','No cuenta por clase: cuenta por tipo de elemento.','estructurales'],
 ':is()':['Agrupa alternativas: basta coincidir con uno de sus argumentos.','Para simplificar listas de selectores relacionadas.','Su especificidad usa el argumento más específico de la lista.','is-where-not'],
 ':where()':['Agrupa alternativas sin añadir especificidad por la función ni sus argumentos.','Para crear estilos base fáciles de sobrescribir.','Tiene especificidad cero, aunque sus argumentos contengan un ID.','is-where-not'],
 ':not()':['Excluye las coincidencias de su argumento.','Para aplicar una regla a todos los párrafos menos los que tienen una clase.','No aumenta la selección fuera del elemento al que se aplica.','is-where-not'],
 ':has()':['Comprueba si existe una coincidencia relativa al elemento; puede responder al estado de un hijo.','Para resaltar una tarjeta que contiene un checkbox marcado.','No se puede anidar :has() dentro de otra :has().','has'],
 '::before':['Genera una caja antes del contenido del elemento.','Para un símbolo o una decoración que no sea información esencial.','Necesita content para generar la caja; no sirve como hijo HTML real.','pseudoelementos'],
 '::after':['Genera una caja después del contenido del elemento.','Para una línea decorativa o un símbolo final.','Necesita content, aunque sea una cadena vacía.','pseudoelementos'],
 '::first-letter':['Representa la primera letra bajo las reglas de formato correspondientes.','Para una inicial editorial destacada.','No es un selector de cualquier primera letra de todos los nodos internos.','pseudoelementos'],
 '::selection':['Representa la parte de un texto que el usuario está seleccionando.','Para ajustar la selección manteniendo contraste.','Solo admite un conjunto limitado de propiedades.','pseudoelementos'],
 '::marker':['Representa el marcador de un elemento de lista.','Para cambiar color o tipografía de viñetas y números.','No admite todas las propiedades de una caja normal.','listas'],
 '::placeholder':['Representa el texto de ayuda provisional de un control.','Para diferenciarlo del valor real sin perder legibilidad.','El placeholder no sustituye un label.','formularios']
};

const ruleTexts={
 '@charset':['Indica una codificación en una hoja CSS externa; debe ocupar la posición y forma exigidas por la detección de codificación.','Para entender archivos CSS y su codificación. En HTML moderno utiliza también meta charset="utf-8".','Dentro de un bloque style no convierte la codificación del documento.','primera-regla'],
 '@counter-style':['Define un sistema de marcadores con nombre que luego puedes usar en list-style-type.','Para viñetas o numeraciones personalizadas.','Definir el sistema no basta: aplícalo a una lista.','listas'],
 '@container':['Aplica reglas cuando el contenedor de referencia cumple una condición.','Para adaptar una tarjeta al espacio donde fue colocada.','Prepara un ancestro con container-type para las consultas de tamaño.','container-queries'],
 '@font-face':['Registra una familia de fuente y el recurso del que debe obtenerse.','Para usar una fuente propia en tu página.','El laboratorio bloquea descargas externas; el ejemplo utiliza una fuente local.','tipografia'],
 '@font-feature-values':['Asigna nombres a conjuntos de características tipográficas para una familia.','Para administrar variantes de una fuente que las ofrezca.','Necesitas una familia y características reales, no solo inventar sus nombres.','tipografia'],
 '@font-palette-values':['Define una paleta personalizada para una fuente de color compatible.','Para elegir colores internos de una fuente que incluya paletas.','No cambia la paleta de una fuente normal que no tenga esas capacidades.','tipografia'],
 '@import':['Importa otra hoja de estilos desde una URL.','Para separar estilos en archivos cuando esa organización te convenga.','Su posición en la hoja importa y el recurso debe poder cargarse; aquí se bloquean recursos externos.','primera-regla'],
 '@keyframes':['Da nombre a una secuencia de estados por los que puede pasar una animación.','Para una animación que tenga inicio, final o pasos intermedios.','Necesitas conectarla con animation-name o animation; definirla no la reproduce.','animaciones'],
 '@layer':['Organiza reglas en capas con un orden de prioridad explícito.','Para separar bases, componentes y utilidades de una hoja grande.','En declaraciones normales, las capas posteriores tienen prioridad sobre las anteriores; con !important el orden se invierte.','capas'],
 '@media':['Aplica reglas cuando se cumple una condición del medio, como el ancho de la vista.','Para rediseñar una página según el espacio o una preferencia del usuario.','Aquí el ancho consultado es el del iframe, no el de todo AprendeCSS.','media-queries'],
 '@namespace':['Declara un prefijo de espacio de nombres para usarlo en selectores.','Para distinguir elementos de distintos vocabularios, como SVG.','La declaración debe preceder a las reglas ordinarias y el prefijo debe coincidir.','combinadores'],
 '@page':['Configura aspectos de las páginas en un medio paginado, como impresión.','Para estudiar márgenes y presentación impresa.','No tiene por qué cambiar una vista normal de pantalla.','impresion'],
 '@position-try':['Define una alternativa de colocación para elementos con posicionamiento anclado.','Para explorar opciones cuando un elemento anclado no cabe.','Requiere un ancla, un elemento posicionado y soporte del navegador.','posicion'],
 '@property':['Registra una variable CSS con tipo, herencia y valor inicial.','Para controlar sus valores y permitir interpolaciones tipadas.','No sustituye var(): el registro y el uso son pasos distintos.','property'],
 '@scope':['Delimita una zona en la que se aplican determinadas reglas.','Para limitar estilos a una parte de la página sin añadir todo el selector raíz a cada regla.','No es un aislamiento completo como Shadow DOM.','scope'],
 '@starting-style':['Define estilos de partida para ciertas transiciones de entrada.','Para que un elemento pueda transicionar desde un estado inicial al aparecer.','Se necesitan una transición compatible y un cambio que active la entrada.','transiciones'],
 '@supports':['Aplica reglas si el navegador reconoce la sintaxis consultada.','Para construir una base funcional y añadir una mejora cuando esté disponible.','Reconocer sintaxis no garantiza que todos los escenarios estén libres de errores.','supports'],
 '@view-transition':['Configura aspectos de las transiciones visuales entre documentos.','Para explorar cambios de vista en navegación compatible.','Un iframe estático no reproduce por sí solo una navegación entre documentos.','transiciones'],
 '@document':['Agrupa reglas con condiciones sobre documentos en implementaciones específicas.','Para reconocer código no estándar o heredado.','No lo tomes como una técnica general de CSS estándar.','supports']
};

function topicFor(name,meta){
 let topic=topics.find(t=>t.test.test(name));
 if(!topic&&meta.groups?.includes('Scalable Vector Graphics'))topic=topics.find(t=>t.lesson==='imagenes'&&t.test.test('fill'));
 if(!topic&&meta.groups?.includes('CSS Logical Properties and Values'))topic=topics.find(t=>t.lesson==='logicas');
 return topic||{lesson:'primera-regla',use:'Resolver una necesidad de su familia de estilos. Comprueba primero el tipo de elemento y el contexto que admite la propiedad.',needs:'Revisa el selector del ejemplo y las condiciones de uso de esta propiedad. Algunas entradas avanzadas requieren otro medio, una estructura o una API.',mistakes:['Un valor reconocido puede no afectar a todos los tipos de elemento.','Cambiar varias reglas a la vez hace más difícil identificar cuál produce el efecto.'],related:[]};
}

function functionInfo(name){
 const n=name.replace('()','');
 if(/^(rgb|rgba|hsl|hsla|hwb|lab|lch|oklab|oklch|color|color-mix|light-dark|alpha)$/.test(n))return {plain:name==='color-mix()'?'Mezcla colores dentro del espacio de color que indiques.':'Construye o transforma un valor de color a partir de sus componentes.',when:'Para elegir un color de texto, fondo o borde y explorar sus componentes.',needs:'La función va dentro de una propiedad que acepte ese color. Conserva las comas, espacios o barras que exige su forma.',mistakes:['Escribir una función de color fuera de una declaración no pinta ningún elemento.','Un color nuevo no garantiza contraste suficiente con el fondo.'],lesson:name==='color-mix()'||/^(ok|lab|lch|color$)/.test(n)?'color-moderno':'colores',related:['color','background-color']};
 if(n.includes('gradient'))return {plain:'Genera una imagen de degradado a partir de colores y posiciones. No necesita un archivo de imagen.',when:'Para fondos con una transición de colores o patrones repetidos.',needs:'Se usa como imagen, por ejemplo en background o background-image. Su forma depende de si es lineal, radial o cónica.',mistakes:['Un degradado no es un <color>: background-color no lo admite.','El orden de colores y posiciones cambia el recorrido del degradado.'],lesson:'fondos',related:['background','background-image']};
 if(/^(blur|brightness|contrast|drop-shadow|grayscale|hue-rotate|invert|opacity|saturate|sepia)$/.test(n))return {plain:'Describe un efecto gráfico dentro de una lista de filtros.',when:'Para modificar el aspecto de una imagen o un componente sin reemplazar su contenido.',needs:'En el ejemplo se usa dentro de filter. Los parámetros y unidades dependen de cada filtro.',mistakes:['opacity() dentro de filter es una función; opacity fuera de filter es otra propiedad.','La cadena de filtros se aplica en orden y puede afectar también al texto.'],lesson:'sombras',related:['filter','backdrop-filter']};
 if(/^(rotate|scale|translate|skew|matrix|perspective)/.test(n))return {plain:'Describe una transformación geométrica: mover, girar, escalar o modificar el dibujo de una caja.',when:'Para ajustar una composición o añadir una respuesta visual a un estado.',needs:'En este ejemplo la función forma parte de transform. Los nombres con X, Y o Z se refieren a ejes concretos.',mistakes:['La transformación no reorganiza el hueco original en el flujo.','Cambiar el orden de varias transformaciones puede cambiar el resultado.'],lesson:'transiciones',related:['transform','transform-origin']};
 if(/^(circle|ellipse|inset|polygon|path|rect|xywh)$/.test(n))return {plain:'Describe una forma geométrica que otra propiedad utiliza.',when:'Para recortar una superficie o describir una forma de contorno.',needs:'El ejemplo coloca la forma dentro de clip-path. Sus coordenadas se calculan según la forma y su caja de referencia.',mistakes:['La forma no se dibuja por existir: necesita una propiedad que la use.','Recortar el dibujo no cambia automáticamente el espacio de layout.'],lesson:'sombras',related:['clip-path','shape-outside']};
 if(/^(minmax|fit-content)$/.test(n))return {plain:'Describe un tamaño o un rango de tamaño para las pistas de una cuadrícula.',when:'Para construir columnas que tengan un mínimo, un máximo o un ajuste al contenido.',needs:'En este ejemplo se usa en grid-template-columns y el contenedor tiene display: grid.',mistakes:['minmax() no es un valor genérico para width: necesita una propiedad que admita tamaños de pista.','Los mínimos pueden impedir que el contenido encoja como esperabas.'],lesson:'grid-fluido',related:['grid-template-columns','grid-auto-columns']};
 if(n==='var')return {plain:'Lee el valor guardado en una propiedad personalizada, como --acento.',when:'Para reutilizar colores, radios y medidas con un nombre.',needs:'La variable debe existir en el alcance adecuado o tener un valor de respaldo.',mistakes:['El nombre dentro de var() lleva los dos guiones.','El respaldo no corrige automáticamente cualquier valor incompatible con la propiedad final.'],lesson:'variables',related:['--*','color']};
 if(n==='attr')return {plain:'Lee un atributo del elemento para utilizarlo en un valor CSS.',when:'Para mostrar un dato de un atributo mediante contenido generado en este ejemplo.',needs:'El ejemplo usa content en ::before y un atributo data-label en HTML. Los usos tipados adicionales tienen sus propias reglas de soporte.',mistakes:['El nombre del atributo debe coincidir con el HTML.','No uses contenido generado como única fuente de información esencial.'],lesson:'pseudoelementos',related:['content']};
 if(/^(counter|counters|symbols)$/.test(n))return {plain:'Construye una representación de contador o de marcadores según la función.',when:'Para numerar pasos o personalizar listas.',needs:'Comprueba el contador o sistema que utiliza el ejemplo; se muestra mediante content o list-style-type según la función.',mistakes:['Incrementar un contador no lo muestra por sí solo.','counter() y counters() no representan la anidación de la misma manera.'],lesson:'listas',related:['content','counter-reset','counter-increment']};
 if(/^(cubic-bezier|steps|linear)$/.test(n))return {plain:'Define el ritmo con el que progresa una animación o una transición.',when:'Para hacer que un movimiento acelere, avance en pasos o siga puntos definidos.',needs:'El ejemplo necesita una animación activa para que puedas comparar su ritmo.',mistakes:['Cambiar la curva no cambia por sí solo la duración total.','Una curva con cambios bruscos puede dificultar seguir el movimiento.'],lesson:'animaciones',related:['animation-timing-function','transition-timing-function']};
 if(/^(calc|min|max|clamp|abs|acos|asin|atan|atan2|cos|sin|tan|exp|log|pow|sqrt|hypot|sign|round|mod|rem|calc-size)$/.test(n))return {plain:({calc:'Calcula un valor combinando operaciones y medidas compatibles.',min:'Elige el menor de los valores de su lista.',max:'Elige el mayor de los valores de su lista.',clamp:'Mantiene un valor preferido entre un mínimo y un máximo.'})[n]||'Calcula un resultado numérico a partir de los argumentos indicados.',when:'Para ajustar medidas o cálculos sin escribir JavaScript.',needs:'El tipo del resultado debe ser compatible con la propiedad. Revisa qué unidades recibe y devuelve la función.',mistakes:['No puedes sumar libremente medidas de tipos incompatibles.','En calc(), deja espacios alrededor de los operadores + y -.'],lesson:'funciones',related:['width','font-size']};
 return {plain:'Construye un valor que necesita el contexto indicado por esta función.',when:'Para una necesidad específica de su familia de CSS; algunas funciones están orientadas a casos avanzados.',needs:'Lee primero «Qué observar» en el laboratorio. Puede requerir una fuente, una API, impresión o una línea temporal adicional.',mistakes:['Pegar la función en cualquier propiedad no garantiza que sea válida.','Una función experimental puede no estar disponible en tu navegador.'],lesson:'supports',related:[]};
}

function selectorInfo(name){const info=selectorTexts[name];if(info)return {plain:info[0],when:info[1],mistakes:[info[2]],lesson:info[3]};return {plain:name.startsWith('::')?'Representa una parte, una caja generada o una superficie especial de un elemento.':'Comprueba una condición del elemento o una relación dentro de la estructura del documento.',when:'Para seleccionar únicamente el estado o la parte del elemento que describe esta entrada.',mistakes:['Una pseudoclase usa : y un pseudoelemento usa ::; no son equivalentes.','Algunos estados requieren interacción, una API o un contexto que un HTML básico no crea.'],lesson:name.startsWith('::')?'pseudoelementos':'hover-focus'};}

function entrySummary(kind,name,meta){
 if(kind==='properties')return specifics[name]?.plain||describeProperty(name,meta);
 if(kind==='selectors')return selectorInfo(name).plain;
 if(kind==='at-rules')return (ruleTexts[name]||['Agrupa instrucciones especiales para el motor CSS.'])[0];
 return functionInfo(name).plain;
}

function explainValue(name,value,meta){
 const explicit=specifics[name]?.values?.[value];if(explicit)return explicit;
 if(/^border(?:-(?:top|right|bottom|left|block|inline))?$/.test(name)&&/\b(solid|dashed|dotted|double)\b/.test(value)){const pieces=value.split(/\s+/);return `Combina el grosor (${pieces[0]}), el tipo de trazo (${pieces[1]}) y el color (${pieces.slice(2).join(' ')}). solid es continuo, dashed discontinuo y dotted punteado.`;}
 if(name==='box-shadow')return value.startsWith('inset')?'inset coloca la sombra hacia dentro. Las medidas siguientes controlan desplazamiento, desenfoque y expansión; el último valor es el color.':'Las medidas controlan desplazamiento horizontal, vertical, desenfoque y, si se incluye, expansión. El último valor es el color de la sombra.';
 if(/^(margin|padding)$/.test(name)){
   const parts=value.trim().split(/\s+/);if(parts.every(p=>/^-?[\d.]+(?:px|rem|em|%)?$/.test(p)))return parts.length===1?'La misma medida en los cuatro lados.':parts.length===2?'Primer valor: arriba y abajo. Segundo: izquierda y derecha.':parts.length===3?'Arriba; izquierda y derecha; abajo.':'Arriba, derecha, abajo e izquierda, en ese orden.';
 }
 if(/^#[\da-f]{3,8}$/i.test(value))return /^(color|.*-color)$/.test(name)?'Un color hexadecimal. Cambia este código para probar otro tono.':'El valor incluye un color hexadecimal; observa qué parte de la propiedad controla.';
 if(value==='initial')return 'Usa el valor inicial definido por CSS. No significa necesariamente el aspecto que el navegador da a esa etiqueta.';
 if(value==='inherit')return 'Toma el valor calculado de la propiedad en el elemento padre.';
 if(value==='auto')return 'Deja que el algoritmo de esta propiedad determine el resultado; no significa siempre «100%». ';
 if(value==='none')return 'Desactiva o retira la función correspondiente de esta propiedad. El efecto exacto depende de cuál sea.';
 if(value==='normal')return 'Utiliza el comportamiento normal definido para esta propiedad y su contexto.';
 if(value==='currentcolor'||value==='currentColor')return 'Reutiliza el color calculado del texto de ese elemento.';
 if(/^\d+(?:\.\d+)?s$/.test(value))return 'Una duración o un desfase expresado en segundos, según esta propiedad.';
 if(/^-?[\d.]+px$/.test(value))return 'Una longitud en píxeles CSS. Un píxel CSS no equivale siempre a un píxel físico de pantalla.';
 if(/^-?[\d.]+rem$/.test(value))return 'Una longitud relativa al tamaño de fuente de la raíz del documento.';
 if(/^-?[\d.]+em$/.test(value))return name==='font-size'?'Una medida relativa al tamaño de fuente del padre.':'Una medida relativa al tamaño de fuente del propio elemento en este uso habitual.';
 if(/^-?[\d.]+%$/.test(value))return name==='font-size'?'Un porcentaje del tamaño de fuente de su referencia heredada.':meta.percentages==='no'?'Esta propiedad no admite porcentajes según el catálogo; revisa el valor y el contexto.':'Un porcentaje de la referencia que define esta propiedad; no presupongas que se refiere a toda la ventana.';
 if(/^-?(?:\d*\.)?\d+$/.test(value))return name==='opacity'?'Opacidad entre 0 y 1.':name==='line-height'?'Multiplica el tamaño de la fuente para obtener la altura de línea.':/^flex-(grow|shrink)$/.test(name)?'Un factor de reparto. No es una longitud en píxeles.':'Un número sin unidad. Su significado depende de la propiedad; no añadas px automáticamente.';
 if(value.includes('fr'))return 'Incluye fracciones del espacio flexible disponible en una cuadrícula; no equivale directamente a un porcentaje.';
 if(value.includes('('))return 'Utiliza una función CSS. Su nombre indica cómo construir o calcular el valor; los paréntesis contienen sus argumentos.';
 return 'Es una palabra clave o combinación de valores admitidos por esta propiedad. Compara su resultado con otra fila y revisa las condiciones de «Antes de probar». ';
}

function grammarNotes(syntax){
 const notes=[];const add=(symbol,meaning)=>notes.push({symbol,meaning});
 if(/<'[^']+'>/.test(syntax))add("<'propiedad'>",'Usa los valores admitidos por esa otra propiedad. Es una referencia de la documentación, no se copia literalmente.');
 if(/<[a-z]/i.test(syntax))add('<tipo>','Un tipo de valor. Por ejemplo, <color> se sustituye por un color real y <length> por una longitud válida.');
 if(syntax.includes('&&'))add('&&','Debes incluir todos esos componentes; el orden puede variar.');
 if(syntax.includes('||'))add('||','Incluye uno o más componentes de ese grupo; el orden puede variar.');
 if(/(^|[^|])\|([^|]|$)/.test(syntax))add('|','Elige una de las alternativas que separa.');
 if(syntax.includes('?'))add('?','El componente anterior es opcional: puede aparecer cero o una vez.');
 if(/(?:>|\])\*/.test(syntax))add('*','El componente puede repetirse cero o más veces.');
 if(/(?:>|\])\+/.test(syntax))add('+','El componente puede repetirse una o más veces.');
 if(/(?:>|\])#/.test(syntax))add('#','La lista admite repeticiones separadas por comas.');
 if(/\{\d+(?:,\d*)?\}/.test(syntax))add('{m,n}','Indica cuántas veces puede aparecer el componente; {1,4} significa de uno a cuatro.');
 if(syntax.includes('['))add('[ ]','Agrupan partes de la definición. Los corchetes de esta notación no se escriben en la declaración final.');
 return notes;
}

function propertyFacts(name,meta){
 if(name==='--*')return {initial:'Sin valor útil hasta definirlo',initialHelp:'Una variable sin registrar debe definirse en el alcance correspondiente o tener un respaldo en var(). --* representa nombres posibles, no una declaración literal.',inherited:'Sí, si no se registra de otra forma',inheritedHelp:'Las propiedades personalizadas sin registrar se heredan. @property puede cambiar su herencia y su valor inicial.',components:[]};
 const initial=Array.isArray(meta.initial)?'Abreviatura: varios componentes':String(meta.initial??'Depende de sus componentes');
 const initialHelp=Array.isArray(meta.initial)?'Cada componente tiene su propio valor inicial. Se detallan más abajo; esta lista no es un valor para pegar en CSS.':`Es el punto de partida definido por CSS. Para forzarlo se escribe ${name}: initial; Las reglas del navegador o de tu página pueden establecer otro valor.`;
 const inherited=meta.inherited===true?'Sí, normalmente pasa a los hijos':meta.inherited===false?'No, cada elemento tiene su valor':'Depende de los componentes';
 const inheritedHelp=meta.inherited===true?'Un hijo recibe este valor si no tiene otra declaración que lo determine. Una regla propia en el hijo puede sustituirlo.':meta.inherited===false?'Poner esta propiedad en el padre no la copia automáticamente a los hijos. inherit permite pedirlo de forma explícita.':'Una propiedad abreviada puede reunir componentes con reglas diferentes de herencia.';
 return {initial,initialHelp,inherited,inheritedHelp,components:Array.isArray(meta.initial)?meta.initial.filter(n=>catalogs.properties[n]).map(n=>({name:n,value:Array.isArray(catalogs.properties[n].initial)?'Tiene sus propios componentes':String(catalogs.properties[n].initial??'Consultar')})):[]};
}

function functionParameters(name){
 const n=name.replace('()','');
 const hints={
  calc:[['Expresión','Combina números o medidas compatibles. Ejemplo: 100% - 30px. Los espacios alrededor de + y - son necesarios.']],
  clamp:[['Primer argumento','El mínimo permitido.'],['Segundo argumento','El valor que prefieres, por ejemplo una medida que responde al ancho.'],['Tercer argumento','El máximo permitido. Mantén un mínimo y un máximo coherentes.']],
  min:[['Lista de valores','Se comparan y se elige el menor valor válido. min(100%, 220px) sirve para no superar 220px ni el ancho disponible.']],
  max:[['Lista de valores','Se comparan y se elige el mayor valor válido. max(50%, 150px) elige el mayor entre esas dos medidas.']],
  minmax:[['Mínimo','El tamaño mínimo de la pista de Grid.'],['Máximo','El tamaño máximo o flexible que puede alcanzar; por ejemplo 1fr.']],
  var:[['Nombre','Empieza por -- y debe coincidir con la variable definida.'],['Respaldo opcional','Se separa con una coma: var(--acento, purple). Se usa si la variable no ofrece un valor disponible válido para la sustitución.']],
  attr:[['Nombre del atributo','Debe existir en el elemento que genera el contenido; el ejemplo utiliza data-label.']],
  rgb:[['Rojo, verde y azul','Definen los canales del color. En la forma habitual numérica, cada uno va de 0 a 255.'],['Alfa opcional','Después de / puedes indicar la opacidad, por ejemplo / 50%.']],
  rgba:[['Canales y alfa','La forma del ejemplo incluye rojo, verde, azul y una opacidad. El alfa 0 es transparente y 1 es opaco.']],
  hsl:[['H: matiz','El ángulo del tono en la rueda de color.'],['S y L','Saturación y luminosidad, expresadas habitualmente en porcentajes.']],
  hsla:[['H, S, L y alfa','Matiz, saturación, luminosidad y opacidad. La función es un alias de hsl() con las mismas formas admitidas.']],
  oklch:[['L: luminosidad','Controla la claridad perceptual del color.'],['C: croma','Controla su intensidad cromática.'],['H: matiz','El ángulo que identifica el tono.']],
  'color-mix':[['Espacio de color','Después de in eliges cómo mezclar, por ejemplo oklch o srgb.'],['Dos colores','Se separan con coma. Un porcentaje indica cuánto aporta ese color.']],
  counter:[['Nombre del contador','Coincide con el que se inicializa o incrementa en el CSS.']],
  counters:[['Nombre y separador','El nombre identifica el contador y la cadena indica cómo unir niveles anidados.']],
  steps:[['Número de pasos','Indica en cuántos saltos se divide la progresión.'],['Posición del salto','Por ejemplo end: el salto se produce según el final de cada intervalo.']],
  'cubic-bezier':[['Cuatro números','Son las coordenadas de dos puntos de control de la curva; las coordenadas X deben estar entre 0 y 1.']],
  blur:[['Radio de desenfoque','Una longitud como 2px. Un valor mayor produce más desenfoque.']],
  opacity:[['Opacidad','Dentro de filter, 0 o 0% es transparente y 1 o 100% es opaco.']],
  'hue-rotate':[['Ángulo','Rota el tono, por ejemplo 90deg.']],
  circle:[['Radio y centro','Describe un círculo; el centro puede indicarse después de at.']],
  polygon:[['Lista de puntos','Cada par indica una coordenada X e Y. Los puntos se unen en el orden escrito.']],
  inset:[['Distancias hacia dentro','Indican cuánto recortar desde los lados. round permite redondear las esquinas del recorte.']]
 };
 if(hints[n])return hints[n];
 if(n.includes('gradient'))return [['Forma o dirección','La parte inicial puede definir una dirección, centro o geometría según el tipo de degradado.'],['Paradas de color','Se separan con comas y pueden llevar posiciones. Su orden define la transición.']];
 if(/^rotate/.test(n))return [['Giro','Las variantes simples usan un ángulo, como 15deg. rotate3d() incluye además un eje definido con tres números.']];
 if(/^translate/.test(n))return [['Desplazamientos','Los parámetros representan desplazamientos según los ejes que indica el nombre. Las longitudes necesitan unidades cuando corresponda.']];
 if(/^scale/.test(n))return [['Factores de escala','1 conserva el tamaño, un valor entre 0 y 1 reduce y un valor mayor que 1 aumenta en el eje correspondiente.']];
 return [['Argumentos de la función','Están entre paréntesis. Conserva las unidades y separadores del ejemplo mientras cambias un argumento cada vez.'],['Propiedad que recibe el resultado','La función debe producir un tipo de valor admitido en la declaración donde la utilizas.']];
}

function getLearningGuide(kind,name,meta,demo,values=[]){
 let info,topic;
 if(kind==='properties'){topic=topicFor(name,meta);info={...topic,...specifics[name],plain:specifics[name]?.plain||describeProperty(name,meta),when:specifics[name]?.when||topic.use};}
 else if(kind==='selectors')info=selectorInfo(name);
 else if(kind==='at-rules'){const text=ruleTexts[name]||['Una instrucción especial de CSS.','Para un contexto específico.','Consulta las condiciones de aplicación.','primera-regla'];info={plain:text[0],when:text[1],mistakes:[text[2]],lesson:text[3]};}
 else info=functionInfo(name);
 const syntax=String(meta.syntax||name);
 const selector=demo.selector||'.demo';
 const targetProperty=name==='--*'?'--acento':name;
 const answer=info.answer||values[1]||values[0];
 let exercise,solution,expectation;
 if(kind==='properties'){
   exercise=info.exercise||`Cambia solo el valor de ${targetProperty} por ${answer}. Ejecuta y compara con el ejemplo original. Si requiere una interacción o un medio concreto, utiliza las condiciones de «Qué observar».`;
   solution=`/* Añade esta regla al final del CSS del ejemplo. */\n${selector} {\n  ${targetProperty}: ${answer};${info.extra?'\n  '+info.extra:''}\n}`;
   expectation=info.expect||'Busca qué parte del elemento cambia y qué parte conserva sus reglas. Si no hay un efecto visible, revisa el contexto, las reglas que compiten y el soporte; no todo valor produce una diferencia visible en cualquier ejemplo.';
 }else if(kind==='selectors'){
   exercise='Identifica qué elemento coincide. Cambia el color de la regla en estudio a #31916e y activa el estado necesario, si lo hay. ¿Cambia todo el documento o solo las coincidencias?';
   solution=demo.css.replace('color: #7951d8;','color: #31916e;');
   expectation='Solo las coincidencias de ese selector reciben la declaración. Un selector sin coincidencias no produce un cambio visible.';
 }else if(kind==='at-rules'){
   const lesson=demo.lesson?lessons.find(l=>l.id===demo.lesson):null;exercise=lesson?.challenge||'Localiza el nombre de la regla y la condición o bloque que contiene. Cambia un parámetro del ejemplo y comprueba cuándo se aplica.';solution=lesson?.solution||demo.css;expectation=lesson?'Compara tu resultado con el objetivo del reto y con las condiciones de esta regla.':'Una regla que necesita impresión, una fuente o una navegación puede no activarse en la vista normal del laboratorio.';
 }else{
   exercise=`Localiza ${name} en el CSS. Cambia un argumento pequeño, conserva su unidad y pulsa Ejecutar. Predice el resultado antes de mirar la vista previa.`;solution=demo.css;expectation='La función debe seguir en una propiedad que admita su resultado. Compara una sola modificación por vez; en funciones de tiempo prueba también el estado o la animación.';
 }
 const related=(info.related||[]).filter(n=>n!==name&&catalogs.properties[n]);
 const lesson=lessons.find(l=>l.id===info.lesson)||lessons[0];
 return {kind,name,plain:info.plain,when:info.when,needs:info.needs||topic?.needs||(kind==='selectors'?'El selector debe encontrar una coincidencia en el HTML o en el estado del navegador. Lee también las condiciones del ejemplo.':kind==='at-rules'?'Las reglas @ tienen una sintaxis propia. Algunas agrupan reglas; otras registran nombres o necesitan otro recurso.':demo.note),mistakes:info.mistakes||topic?.mistakes||[],values:values.slice(0,6).map(value=>({value,meaning:explainValue(name,value,meta)})),parameters:kind==='functions'?functionParameters(name):[],facts:kind==='properties'?propertyFacts(name,meta):null,grammar:grammarNotes(syntax),exercise,solution,expectation,lesson:{id:lesson.id,title:lesson.title},related,selector,targetProperty,essential:!!specifics[name]||!!selectorTexts[name],syntax};
}

Object.assign(window.CSSLab,{entrySummary,getLearningGuide});
})();
